// lib/providers/storage/supabase.ts
var BUCKET = "clips";
var SupabaseStorageProvider = class {
  async ensureBucket() {
    const client2 = getSupabaseClient();
    const { data: buckets } = await client2.storage.listBuckets();
    const exists = buckets?.some((b) => b.name === BUCKET);
    if (!exists) {
      const { error } = await client2.storage.createBucket(BUCKET, { public: true });
      if (error) throw new Error(`Falha ao criar bucket: ${error.message}`);
    }
  }
  async upload(key, buffer, contentType) {
    const client2 = getSupabaseClient();
    await this.ensureBucket();
    const { error } = await client2.storage.from(BUCKET).upload(key, buffer, { contentType, upsert: true });
    if (error) throw new Error(`Supabase upload falhou: ${error.message}`);
    const { data } = client2.storage.from(BUCKET).getPublicUrl(key);
    return data.publicUrl;
  }
  async cleanup(maxAgeMs) {
    const client2 = getSupabaseClient();
    const cutoff = new Date(Date.now() - maxAgeMs).toISOString();
    const { data: folders } = await client2.storage.from(BUCKET).list("", { limit: 1e3 });
    if (!folders) return 0;
    let deleted = 0;
    for (const folder of folders) {
      if (folder.created_at && folder.created_at < cutoff) {
        const { data: files } = await client2.storage.from(BUCKET).list(folder.name);
        if (files?.length) {
          const paths = files.map((f) => `${folder.name}/${f.name}`);
          await client2.storage.from(BUCKET).remove(paths);
          deleted += paths.length;
        }
      }
    }
    return deleted;
  }
};

// lib/providers/storage/index.ts
function createStorageProvider() {
  const provider = process.env.STORAGE_PROVIDER || "supabase";
  switch (provider) {
    case "supabase":
      return new SupabaseStorageProvider();
    case "local":
      return new LocalStorageProvider();
    default:
      throw new Error(`Storage provider desconhecido: "${provider}". Use "supabase" ou "local".`);
  }
}

// lib/providers/social/youtube.ts
var YouTubeProvider = class {
  constructor() {
    this.platform = "youtube";
  }
  async publish({ videoUrl, title, description = "", accessToken }) {
    const videoRes = await fetch(videoUrl);
    if (!videoRes.ok) throw new Error(`Falha ao baixar v\xEDdeo: ${videoRes.statusText}`);
    const videoBuffer = Buffer.from(await videoRes.arrayBuffer());
    const contentLength = videoBuffer.byteLength;
    const initRes = await fetch(
      "https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json",
          "X-Upload-Content-Type": "video/mp4",
          "X-Upload-Content-Length": String(contentLength)
        },
        body: JSON.stringify({
          snippet: {
            title: title.slice(0, 100),
            description,
            categoryId: "22"
            // People & Blogs
          },
          status: {
            privacyStatus: "public",
            selfDeclaredMadeForKids: false
          }
        })
      }
    );
    if (!initRes.ok) {
      const err = await initRes.text();
      throw new Error(`YouTube init upload falhou: ${err}`);
    }
    const uploadUri = initRes.headers.get("location");
    if (!uploadUri) throw new Error("YouTube n\xE3o retornou upload URI");
    const uploadRes = await fetch(uploadUri, {
      method: "PUT",
      headers: {
        "Content-Type": "video/mp4",
        "Content-Length": String(contentLength)
      },
      body: videoBuffer
    });
    if (!uploadRes.ok && uploadRes.status !== 200 && uploadRes.status !== 201) {
      const err = await uploadRes.text();
      throw new Error(`YouTube upload falhou: ${err}`);
    }
    const data = await uploadRes.json();
    const videoId = data.id;
    if (!videoId) throw new Error("YouTube n\xE3o retornou video ID");
    return {
      platformPostId: videoId,
      platformPostUrl: `https://www.youtube.com/shorts/${videoId}`
    };
  }
  async refreshAccessToken(refreshToken) {
    const res = await fetch("https://oauth2.googleapis.com/token", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "refresh_token",
        refresh_token: refreshToken,
        client_id: process.env.GOOGLE_CLIENT_ID,
        client_secret: process.env.GOOGLE_CLIENT_SECRET
      })
    });
    if (!res.ok) throw new Error(`YouTube token refresh falhou: ${await res.text()}`);
    const data = await res.json();
    return {
      accessToken: data.access_token,
      refreshToken: data.refresh_token ?? refreshToken,
      expiresAt: new Date(Date.now() + data.expires_in * 1e3)
    };
  }
};

// lib/providers/social/tiktok.ts
var TIKTOK_API = "https://open.tiktokapis.com/v2";
var TikTokProvider = class {
  constructor() {
    this.platform = "tiktok";
  }
  async publish({ videoUrl, title, accessToken }) {
    const initRes = await fetch(`${TIKTOK_API}/post/publish/video/init/`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": "application/json; charset=UTF-8"
      },
      body: JSON.stringify({
        post_info: {
          title: title.slice(0, 150),
          privacy_level: "PUBLIC_TO_EVERYONE",
          disable_duet: false,
          disable_comment: false,
          disable_stitch: false,
          video_cover_timestamp_ms: 1e3
        },
        source_info: {
          source: "PULL_FROM_URL",
          video_url: videoUrl
        }
      })
    });
    if (!initRes.ok) {
      const err = await initRes.text();
      throw new Error(`TikTok init falhou: ${err}`);
    }
    const initData = await initRes.json();
    if (initData.error?.code && initData.error.code !== "ok") {
      throw new Error(`TikTok init erro: ${initData.error.message}`);
    }
    const publishId = initData.data?.publish_id;
    if (!publishId) throw new Error("TikTok n\xE3o retornou publish_id");
    const postId = await this.pollPublishStatus(publishId, accessToken);
    return {
      platformPostId: postId,
      platformPostUrl: `https://www.tiktok.com/@me/video/${postId}`
    };
  }
  async pollPublishStatus(publishId, accessToken) {
    const maxAttempts = 30;
    const delayMs = 5e3;
    for (let i = 0; i < maxAttempts; i++) {
      await new Promise((r) => setTimeout(r, delayMs));
      const res = await fetch(`${TIKTOK_API}/post/publish/status/fetch/`, {
        method: "POST",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json; charset=UTF-8"
        },
        body: JSON.stringify({ publish_id: publishId })
      });
      if (!res.ok) continue;
      const data = await res.json();
      const status = data.data?.status;
      if (status === "PUBLISH_COMPLETE") {
        return data.data?.publicaly_available_post_id?.[0] ?? publishId;
      }
      if (status === "FAILED") {
        throw new Error(`TikTok publica\xE7\xE3o falhou: ${data.data?.fail_reason ?? "erro desconhecido"}`);
      }
    }
    throw new Error("TikTok: timeout aguardando publica\xE7\xE3o");
  }
  async refreshAccessToken(refreshToken) {
    const res = await fetch(`${TIKTOK_API}/oauth/token/`, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        grant_type: "refresh_token",
        refresh_token: refreshToken,
        client_key: process.env.TIKTOK_CLIENT_KEY,
        client_secret: process.env.TIKTOK_CLIENT_SECRET
      })
    });
    if (!res.ok) throw new Error(`TikTok token refresh falhou: ${await res.text()}`);
    const data = await res.json();
    return {
      accessToken: data.access_token,
      refreshToken: data.refresh_token ?? refreshToken,
      expiresAt: new Date(Date.now() + data.expires_in * 1e3)
    };
  }
};

// lib/providers/social/instagram.ts
var GRAPH_API = "https://graph.instagram.com/v21.0";
var InstagramProvider = class {
  constructor() {
    this.platform = "instagram";
  }
  async publish({ videoUrl, title, accessToken, platformUserId }) {
    if (!platformUserId) throw new Error("Instagram requer platformUserId (ig_user_id)");
    const containerRes = await fetch(
      `${GRAPH_API}/${platformUserId}/media?access_token=${accessToken}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          media_type: "REELS",
          video_url: videoUrl,
          caption: title,
          share_to_feed: true
        })
      }
    );
    if (!containerRes.ok) {
      const err = await containerRes.text();
      throw new Error(`Instagram container falhou: ${err}`);
    }
    const { id: containerId } = await containerRes.json();
    if (!containerId) throw new Error("Instagram n\xE3o retornou container ID");
    await this.pollContainerStatus(containerId, accessToken);
    const publishRes = await fetch(
      `${GRAPH_API}/${platformUserId}/media_publish?access_token=${accessToken}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          creation_id: containerId
        })
      }
    );
    if (!publishRes.ok) {
      const err = await publishRes.text();
      throw new Error(`Instagram publish falhou: ${err}`);
    }
    const { id: mediaId } = await publishRes.json();
    return {
      platformPostId: mediaId,
      platformPostUrl: `https://www.instagram.com/p/${mediaId}/`
    };
  }
  async pollContainerStatus(containerId, accessToken) {
    const maxAttempts = 24;
    const delayMs = 5e3;
    for (let i = 0; i < maxAttempts; i++) {
      await new Promise((r) => setTimeout(r, delayMs));
      const res = await fetch(
        `${GRAPH_API}/${containerId}?fields=status_code&access_token=${accessToken}`
      );
      if (!res.ok) continue;
      const data = await res.json();
      if (data.status_code === "FINISHED") return;
      if (data.status_code === "ERROR" || data.status_code === "EXPIRED") {
        throw new Error(`Instagram container falhou com status: ${data.status_code}`);
      }
    }
    throw new Error("Instagram: timeout aguardando container");
  }
  async refreshAccessToken(accessToken) {
    const res = await fetch(
      `https://graph.instagram.com/refresh_access_token?grant_type=ig_refresh_token&access_token=${accessToken}`
    );
    if (!res.ok) throw new Error(`Instagram token refresh falhou: ${await res.text()}`);
    const data = await res.json();
    return {
      accessToken: data.access_token,
      expiresAt: new Date(Date.now() + (data.expires_in ?? 5184e3) * 1e3)
    };
  }
};

// lib/providers/social/index.ts
function createSocialProvider(platform) {
  switch (platform) {
    case "youtube":
      return new YouTubeProvider();
    case "tiktok":
      return new TikTokProvider();
    case "instagram":
      return new InstagramProvider();
    default:
      throw new Error(`Plataforma social desconhecida: "${platform}"`);
  }
}

